/* Generated by `pnpm kit:gen` (kit/compile.ts) from kit/fields/demo.ts: edit that file, never this one.
   demoField, the effect's kernel, in GLSL ES 3.00 (the player, the WebGL page) and in WGSL (the WebGPU page),
   and its cost an evaluation. */
export const KERNEL_GLSL = `uniform vec4 uK_shear[2];
uniform vec4 uK_wave[5];
uniform vec4 uKF[2];

float kfield(float x, float y) {
  float px = x;
  float py = y;
  for (int i = 0; i < 2; i++) {
    float dx = uK_shear[i].x;
    float dy = uK_shear[i].y;
    float s = sin(uK_shear[i].z * (dx * px + dy * py) + uKF[0][i]) * uK_shear[i].w;
    px -= dy * s;
    py += dx * s;
  }
  float f = 0.6 * px;
  for (int i = 0; i < 5; i++) {
    float s = uK_wave[i].z * (uK_wave[i].x * px + uK_wave[i].y * py) + uKF[(i + 2) / 4][(i + 2) % 4];
    f += uK_wave[i].w * sin(s);
  }
  return f;
}`;

export const KERNEL_WGSL = `struct KitKernel {
  shear: array<vec4f, 2>,
  wave: array<vec4f, 5>,
  f: array<vec4f, 2>,
}

fn kfield(x: f32, y: f32) -> f32 {
  var px: f32 = x;
  var py: f32 = y;
  for (var i: i32 = 0; i < 2; i++) {
    let dx: f32 = kk.shear[i].x;
    let dy: f32 = kk.shear[i].y;
    let s: f32 = sin(kk.shear[i].z * (dx * px + dy * py) + kk.f[0][i]) * kk.shear[i].w;
    px -= dy * s;
    py += dx * s;
  }
  var f: f32 = 0.6 * px;
  for (var i: i32 = 0; i < 5; i++) {
    let s: f32 = kk.wave[i].z * (kk.wave[i].x * px + kk.wave[i].y * py) + kk.f[(i + 2) / 4][(i + 2) % 4];
    f += kk.wave[i].w * sin(s);
  }
  return f;
}`;

export const KERNEL_COST = 112;
